import{_ as a,H as o,f as n,i}from"./chunks/framework.BauLNg70.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Mods para Snake Classic","text":"Doc oficial para autores de mods.","tagline":"Personaliza power-ups, velocidad, progresión y UI sin compilar el\\njuego. Sandbox por diseño, compatible con cualquier bundle del\\nestudio (standalone + Classics Reloaded).\\n","actions":[{"theme":"brand","text":"Empezar","link":"/getting-started"},{"theme":"alt","text":"Mira el template","link":"https://github.com/leteoworks/mod-template-snake-classic"},{"theme":"alt","text":"Steam Workshop","link":"https://steamcommunity.com/app/TBD/workshop/"}]},"features":[{"icon":"📦","title":"Manifest declarativo","details":"Un solo `mod.json` describe permisos, engine, eventos, settings UI,\\nassets, i18n. El framework valida con Zod antes de cargar.\\n","link":"/manifest-format"},{"icon":"🎛️","title":"UI con componentes oficiales","details":"No tienes que pelear con CSS. Declara tabs/sliders/toggles con\\ntokens semánticos y el juego renderiza con su look coherente.\\n","link":"/storybook/index.html"},{"icon":"🔐","title":"Sandbox por diseño","details":"Sin `fetch`, sin `window`, sin `require`. El host expone una API\\ncontrolada y el juego garantiza que un mod no puede tirarlo.\\n","link":"/api-reference"},{"icon":"🚀","title":"Workshop nativo","details":"Publica desde Steam → un `.zip` con tu manifest + dist y listo.\\nAuto-update, auto-discovery, kill-switch reactivo del estudio.\\n","link":"/publishing"},{"icon":"🧩","title":"Multi-engine","details":"Elige el motor según tus necesidades. QuickJS por defecto;\\nisolated-vm, iframe-sandbox, web-worker-offscreen-canvas u otros\\nsegún features.\\n","link":"/multi-engine"},{"icon":"🎯","title":"Targeting al `gameId`","details":"Tu mod apunta a `snake-classic` y funciona en cualquier bundle\\nque monte el juego (standalone, Classics Reloaded…). Sin\\nduplicar publicaciones.\\n","link":"/targeting-games"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"};function s(r,e,l,d,c,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<h2 id="¿que-encontraras-aqui" tabindex="-1">¿Qué encontrarás aquí? <a class="header-anchor" href="#¿que-encontraras-aqui" aria-label="Permalink to &quot;¿Qué encontrarás aquí?&quot;">​</a></h2><ul><li><strong>Tutoriales</strong> paso a paso para tu primer mod.</li><li><strong>Referencia completa</strong> del <code>mod.json</code> y del <code>HostBridge</code>.</li><li><strong>Catálogo visual</strong> de componentes UI declarativos disponibles.</li><li><strong>Guía de publicación</strong> a Steam Workshop (incluyendo flow de verificación opcional cuando se active).</li><li><strong>Ejemplos reales</strong> clonables — empezando por el mod oficial &quot;Fun Config&quot; que sirve de referencia viva.</li></ul><h2 id="¿quien-mantiene-esto" tabindex="-1">¿Quién mantiene esto? <a class="header-anchor" href="#¿quien-mantiene-esto" aria-label="Permalink to &quot;¿Quién mantiene esto?&quot;">​</a></h2><p>El portal lo mantiene el equipo de Leteo Works. Issues, sugerencias y PRs vienen por GitHub. Bugs del juego o del runtime van por el repo principal; bugs de docs vienen aquí.</p><h2 id="conducta-esperada-de-la-comunidad" tabindex="-1">Conducta esperada de la comunidad <a class="header-anchor" href="#conducta-esperada-de-la-comunidad" aria-label="Permalink to &quot;Conducta esperada de la comunidad&quot;">​</a></h2><p>Mods que ejecuten malware, doxxen jugadores, o filtren datos serán <strong>reportados a Steam y kill-switch-eados</strong> desde nuestro panel de operación. El sandbox del runtime ya impide la mayoría de vectores, pero la responsabilidad final es del modder.</p><p>Para todo lo demás: enjoy + experimenta sin miedo. Hacer mods debe ser divertido.</p>',7)])])}const g=a(t,[["render",s]]);export{m as __pageData,g as default};
